    if (typeof this.game.buildMinimapState === 'function') {
      return this.game.buildMinimapState();
    }
    const p = this.game.player;
    return {
      roads: [],
      police: [],
      waypoint: null,
      player: p && p.position ? { x: p.position.x, z: p.position.z } : { x: 0, z: 0 },
      range: 760,
      heading: p ? p.heading : 0,
